   153  std::string BmffImage::uuidName(const Exiv2::DataBuf& uuid) {
   154    const char* uuidCano = "\x85\xC0\xB6\x87\x82\xF\x11\xE0\x81\x11\xF4\xCE\x46\x2B\x6A\x48";
   155    const char* uuidXmp = "\xBE\x7A\xCF\xCB\x97\xA9\x42\xE8\x9C\x71\x99\x94\x91\xE3\xAF\xAC";
   156    const char* uuidCanp = "\xEA\xF4\x2B\x5E\x1C\x98\x4B\x88\xB9\xFB\xB7\xDC\x40\x6E\x4D\x16";
   157    if (uuid.cmpBytes(0, uuidCano, 16) == 0)
   158      return "cano";
   159    if (uuid.cmpBytes(0, uuidXmp, 16) == 0)
   160      return "xmp";
   161    if (uuid.cmpBytes(0, uuidCanp, 16) == 0)
   162      return "canp";
   163    return "";
   164  }
