   192  void BmffImage::brotliUncompress(const byte* compressedBuf, size_t compressedBufSize, DataBuf& arr) {
   193    BrotliDecoderWrapper decoder;
   194    size_t uncompressedLen = compressedBufSize * 2;  // just a starting point
   195    BrotliDecoderResult result;
   196    int dos = 0;
   197    size_t available_in = compressedBufSize;
   198    const byte* next_in = compressedBuf;
   199    size_t available_out;
   200    byte* next_out;
   201    size_t total_out = 0;
   202
   203    do {
   204      arr.alloc(uncompressedLen);
   205      available_out = uncompressedLen - total_out;
   206      next_out = arr.data() + total_out;
   207      result =
   208          BrotliDecoderDecompressStream(decoder.get(), &available_in, &next_in, &available_out, &next_out, &total_out);
   209      if (result == BROTLI_DECODER_RESULT_SUCCESS) {
   210        arr.resize(total_out);
   211      } else if (result == BROTLI_DECODER_RESULT_NEEDS_MORE_OUTPUT) {
   212        uncompressedLen *= 2;
   213        // DoS protection - can't be bigger than 128k
   214        if (uncompressedLen > 131072) {
   215          if (++dos > 1)
   216            break;
   217          uncompressedLen = 131072;
   218        }
   219      } else if (result == BROTLI_DECODER_RESULT_NEEDS_MORE_INPUT) {
   220        // compressed input buffer in incomplete
   221        throw Error(ErrorCode::kerFailedToReadImageData);
   222      } else {
   223        // something bad happened
   224        throw Error(ErrorCode::kerErrorMessage, BrotliDecoderErrorString(BrotliDecoderGetErrorCode(decoder.get())));
   225      }
   226    } while (result != BROTLI_DECODER_RESULT_SUCCESS);
   227
   228    if (result != BROTLI_DECODER_RESULT_SUCCESS) {
   229      throw Error(ErrorCode::kerFailedToReadImageData);
   230    }
   231  }
