   401      // 8.11.3.1
   402      case TAG_iloc: {
   403        Internal::enforce(data.size() - skip >= 2, Exiv2::ErrorCode::kerCorruptedMetadata);
   404        uint8_t u = data.read_uint8(skip++);
   405        uint16_t offsetSize = u >> 4;
   406        uint16_t lengthSize = u & 0xF;
   407  #if 0
   408                  uint16_t indexSize  = 0       ;
