   417        uint32_t itemCount = version < 2 ? data.read_uint16(skip, endian_) : data.read_uint32(skip, endian_);
   418        skip += version < 2 ? 2 : 4;
   419        if (itemCount && itemCount < box_length / 14 && offsetSize == 4 && lengthSize == 4 &&
   420            ((box_length - 16) % itemCount) == 0) {
   421          if (bTrace) {
   422            out << std::endl;
   423            bLF = false;
   424          }
   425          auto step = (static_cast<size_t>(box_length) - 16) / itemCount;  // length of data per item.
   426          size_t base = skip;
   427          for (uint32_t i = 0; i < itemCount; i++) {
   428            skip = base + i * step;  // move in 14, 16 or 18 byte steps
   429            Internal::enforce(data.size() - skip >= (version > 2u ? 4u : 2u), Exiv2::ErrorCode::kerCorruptedMetadata);
   430            Internal::enforce(data.size() - skip >= step, Exiv2::ErrorCode::kerCorruptedMetadata);
