   468          pixelHeight_ = height;
   469        }
   470      } break;
   471
   472      // 12.1.5.2
   473      case TAG_colr: {
   474        if (data.size() >= (skip + 4 + 8)) {  // .____.HLino..__mntrR 2 0 0 0 0 12 72 76 105 110 111 2 16 ...
   475          // https://www.ics.uci.edu/~dan/class/267/papers/jpeg2000.pdf
   476          uint8_t meth = data.read_uint8(skip + 0);
